"""Q42: add Q42 entries to /output/report.json and annotate entries 216 (Q40) and 104 (H13CN opacity bounds) (idempotent). usage: python3 -I s251_update_report_q42.py"""
import json
R=json.load(open('/output/report.json'))
R['results']=[x for x in R['results'] if not str(x.get('quantity','')).startswith('Q42')]
MK=' [Q42 note: '
for x in R['results']:
    if MK in str(x.get('value','')): x['value']=x['value'][:x['value'].index(MK)]
def ann(prefix,txt):
    for x in R['results']:
        if str(x.get('quantity','')).startswith(prefix): x['value']=x['value']+MK+txt+']'; return
    raise KeyError(prefix)
EV0='/workspace/scripts/s250a_q42_h13cn_grid.py, s250b_q42_ratio_fit.py (fits), s250c_q42_analysis.py -> out/q42/analysis.txt/json, fit_*.npz; s250d_q42_branch_predictions.py -> out/q42/branch_predictions.txt, branch_ratio_terms.txt; s250e_q42_common_taper_ratios.py -> out/q42/common_taper_ratios.txt; run scripts out/q42/run_all*.sh'
ann('Optical-depth bounds from the H13CN limit',"the analytic bounds above assume equal Tex for HCN and H13CN. With non-LTE RADEX (own H13CN LAMDA file) the radiative trapping of the thick HCN lines raises its 4-3 excitation relative to the thin H13CN, so the predicted alpha=I(H13CN 4-3)/I(HCN 4-3) stays 0.016-0.035 for every Tk branch and X=32-63 even at tau(HCN 4-3)=11-19 (Q42, out/q42/branch_predictions.txt): the alpha<0.12 limit (and any 4-3 value of precision +-0.04) does NOT constrain the opacity or the Tk branch; use these tau limits only as equal-Tex statements")
ann('Q40: can the 13C isotopologue data',"Q42 shows (i) adding the H13CN 4-3 ratio changes nothing (P(Tk<=30) 0.0026 vs 0.0021, X_N 33), (ii) the exclusion of the cold branch depends on the 13C data used: with Harada 1.7 arcsec peak-pixel H13CO+ (X_N~33) P(Tk<=30)=0.002 (band priors 10/15%); with 2.2 arcsec common-taper 13C/12C ratios at N (aperture 0.0231, X_N 58 [48,68]) 0.005-0.014, peak-pixel 0.04-0.06, and with the 20/25% band priors 0.2-0.5 (BF hot:cold 1-4): the cold/thick branch is disfavoured only for tight band-scale priors; (iii) the X_S/X_N contrast (85/33=2.6) shrinks to 1.3-1.8 [1.0,2.4] at one 2.2 arcsec taper (P(X_S>X_N)=0.6-0.93). See the Q42 entries")
ASM=[dict(name='model',value='Q40r2 one-zone RADEX fine grid (s220b/s230/s235 machinery) with the Harada 1.7" 12C lines unchanged; added same-line 13C/12C ratio terms (filling factor and band scale cancel): R=I(13C)/I(12C) K km/s from RADEX at N(13C)=N(12C)/X, same Tk, n, width; X on a 0.05-0.1 dex grid 22-178 (flat in log X, or LN(45,0.2 dex)); band-scale priors 10/15% and 20/25%; sigma^2 = err^2 + (10% R_mod)^2. H13CN uses its own LAMDA file h13cn@xpol.dat (HCN-file convention gives a 1.2-1.7x LOWER 4-3 H13CN emission at Tk 25-100 K, so it would be even less constraining); H13CO+ uses the HCO+ file (no H13CO+ file installed).'),
     dict(name='data',value='H13CN 4-3 (Xb47 spw20, 4.26x2.77"; HCN 4-3 template from spw16 of the same OUS, beam 4.14x2.70", so NOT the same cube: 3% beam difference, not corrected): alpha(flux)=I(H13CN)/I(HCN)=0.045+-0.04 (accepted wing models of s41, centres 0-0.095) at N, 3-sigma limit 0.12; censored version R=0+-0.04; S 0.01+-0.05 (UL 0.135-0.17), Bridge 0.03+-0.07 (UL 0.06-0.19); T_b ratio = alpha*(354.5055/345.3398)^2. 2.2" common-taper ratios from Q29 s185 (X961 12C, X95d 13C, 2015.1.00993). H13CN 3-2 (259.012 GHz rest, 256.6 GHz sky) and H13CO+ 3-2 (260.255; 257.8 GHz sky) are NOT covered by the Band 6 tuning (249.0-252.6, 262.8-266.4 GHz sky).'),
     dict(name='limits',value='The 13C/12C ratios are measured at 2.2" (native beam 2.1x1.7"; 1.7" itself is not reachable) while the 12C lines are Harada 1.7" peak pixels: the beam/aperture mismatch is common to N, S, C so contrasts are cleaner than absolute X, but the absolute N result moves with the extraction (aperture vs peak). One zone; X>100 is unconstrained for S (X_S is a lower bound).')]
R['results'].append(dict(quantity='Q42a: H13CN(4-3)/HCN(4-3) as an extra opacity constraint (censored limit at N; S, C limits) in the Q40 one-gas RADEX fit with N(H13CN)=N(HCN)/X, same X nuisance',
 target='N (also S, Bridge); Xb47 4.3x2.8" ratio applied to the 1.7" gas as a same-gas ratio (beam dilution cancels only if both species fill alike; f=0.35 dilution variant run)',
 value=('RESULT: NO additional constraint. The H13CN 4-3 data (alpha<0.12 3-sigma, or 0.045+-0.04 fitted) leave the N fit unchanged: P(Tk<=30 K) = 0.0026 (censored) / 0.0018 (fitted) / 0.020 (dilution f=0.35, 20/25% priors; baseline 0.016) vs 0.0021 without it (band priors 10/15%, X prior LN(45,0.2dex)); X_N 32-33 [27,42] unchanged; N(HCN)/N(HCO+) 3.49 [3.15,3.85] unchanged; BF hot:cold 380-540 vs 457. Reason (RADEX, out/q42/branch_predictions.txt): the model alpha is 0.016-0.035 in ALL branches (cold Tk<=30 K, tau(HCN 4-3)=7-19: alpha 0.019-0.033; hot Tk 211-300 K, tau 0.7-14: 0.016-0.033) because non-LTE trapping raises the 4-3 excitation of the thick HCN line, so the equal-Tex relation ratio~tau/X of Q4 does not hold; the limit is 4-7x above any prediction and a measurement would have to reach ~+-0.005 to separate branches (and the branch predictions differ by <40%). The discriminating H13CN datum is 1-0 (model H13CN/HCN 1-0: 0.12-0.13 cold, 0.085-0.09 mid, 0.04-0.06 hot vs 0.0207+-0.0034 observed at 2.2"): see Q42b. '
        'STATED PLAINLY: H13CN 3-2 (256.6 GHz sky) and H13CO+ 3-2 (257.8 GHz sky) are not covered by the Xb4f/Xb4d/Xb4b tuning (249.0-252.6 and 262.8-266.4 GHz sky), so there is no H13CN 3-2 constraint; H13CN 4-3 is the only H13CN rotational line above 1-0 and sits on the CO 3-2 blue wing (Q4: wing-model dependent, centres 0-0.095). HCN 4-3 (spw16) and H13CN 4-3 (spw20) are different spws of one OUS (beams 4.14x2.70 and 4.26x2.77"), not one cube.'),
 unit='probability; dimensionless',uncertainty='alpha wing-model envelope +-0.04 (3-sigma limit 0.12); P(Tk<=30) +-factor 2 from the X prior',
 confidence='medium',evidence=EV0,assumptions=ASM))
R['results'].append(dict(quantity='Q42b: H13CO+/HCO+ and H13CN/HCN at N, S, C at ONE common 2.2" taper and the X=12C/13C contrast (X_N~31-35 vs X_S~65-85 of Q40)',
 target='N, S, C(Bridge): 2.2" circular beam (X961 + X95d, short-spacing complete), template aperture r<2.2", +-150 km/s aperture, +-150 km/s peak pixel; Harada 1.7" N, C for comparison',
 value=('Ratios (R=I(13C)/I(12C), K km/s): H13CO+/HCO+ template aperture N 0.0231+-0.0031, S 0.0184+-0.0040, C 0.0185+-0.0033 (thin 12C/13C 43 [38,50], 54 [45,69], 54 [46,66]); +-150 aperture N 0.0271+-0.0049, S 0.0150+-0.0047, C 0.0182+-0.0045 (37, 67, 55); peak pixel N 0.0372+-0.0066, S 0.0141+-0.0088, C 0.0222+-0.0087 (27, 71 [44,189], 45); Harada 1.7" peak N 0.0458+-0.0049 (22+-3), C 0.0247+-0.0069. H13CN/HCN template aperture N 0.0207+-0.0034, S 0.0057+-0.0059 (<0.0177 3 sigma), C 0.0237+-0.0044; peak N 0.0302+-0.0058, S -0.0006+-0.0130, C 0.0265+-0.0117. N ratio falls 2x (22 -> 43) from the 1.7" peak pixel to the 2.2" aperture. '
        'MODEL-FREE contrast N vs S: R_N-R_S (H13CO+) = +0.0047+-0.0051 (0.9 sigma, template ap.), +0.0121+-0.0068 (1.8 sigma, +-150 ap.), +0.0231+-0.0110 (2.1 sigma, peak); H13CN: +0.015+-0.0068 (2.2 sigma), +0.017+-0.008, +0.031+-0.014 (2.2 sigma); N vs C 0-1.4 sigma (H13CO+) and -0.5 to +0.3 sigma (H13CN). '
        'RADEX (one-gas, 12C Harada 1.7" lines + these ratios as same-line ratio terms, X marginalised, LN(45,0.2dex) prior, band priors 10/15%): X_N = 58 [48,68] (aperture), 41 [34,53] (peak), 50 [43,59] (aperture + Harada 3-2 ratio) versus 33 [27,41] with Harada intensities; X_S = 84 [70,95] (X<=100; 99 [76,119] to X<=178) aperture, 76 [60,93] peak; X_C = 52 [45,64]. CONTRAST X_S/X_N = 1.3 [1.0,1.6] (aperture), 1.8 [1.2,2.2] (peak), 1.5 [1.2,1.8] (+3-2), P(X_S>X_N) = 0.89-0.95 for tight band priors, 1.0-1.2 [0.9,1.9] and P = 0.6-0.75 with 20/25% band priors; i.e. the Q40 contrast (X_S 78-85 vs X_N 31-35, factor 2.5) was mostly a beam/aperture artefact (Harada 1.7" peak at N vs 2.2" S); at one taper the contrast is <=1.8 and <=2 sigma, the S value is a lower bound (X_S>~65). X_N~X_C~52-58 (aperture). H13CN (S 0.006+-0.006) is the stronger N/S discriminator (2.2 sigma) than H13CO+ (0.9-2 sigma): opacity (HCN thicker at N, HCN/HCO+ higher) or a real isotopic gradient cannot be separated.'),
 unit='dimensionless; 12C/13C',uncertainty='ratios: null-aperture-calibrated (Q29 s185) incl. 8% cross-project scale; X: 16-84% of marginal posterior; beam/aperture choice (aperture vs peak) moves X_N by 1.4x',
 confidence='medium',evidence=EV0+'; out/q29/s185.json (ratios)',assumptions=ASM))
R['results'].append(dict(quantity='Q42c: does the exclusion of the cold/dense thick RADEX branch at N survive a common-taper 13C/12C ratio set (aperture, peak pixel, + Harada 3-2) and loose band scales?',
 target='N (12C Harada 1.7" lines + 2.2" 13C/12C ratios); S and C as supplements',
 value=('P(Tk<=30 K), LN(45,0.2dex) X prior (X<=100): Harada intensities (Q40) 0.002 (10/15% band priors), 0.016 (20/25%), 0.025 (40/40%); common-taper aperture ratios 0.005-0.014 / 0.20-0.28; peak-pixel ratios 0.04-0.06 / 0.47-0.51; aperture + Harada 3-2 0.02-0.07 / 0.46-0.58 (BF hot:cold 218/4, 23/1, 45/1). Extending X to 178 (flat) raises P(cold) to 0.15-0.56 (10/15%) because X>100 leaves the branches degenerate. CONCLUSION: the cold/dense thick branch at N is disfavoured (P<=0.07) only with tight (10/15%) band-scale priors; with 20/25% band scales or an aperture-averaged 13C/12C it is NOT excluded (P 0.2-0.5), so the Q40/p0044 statement must be reduced to "disfavoured given the beam-matched 1.7" H13CO+ and tight 1-0/3-2 scales". Hot (Tk>=100 K) remains the best-fit branch in all variants; N(HCN)/N(HCO+) = 3.4 [3.1,3.7] on the hot branch (all tight-prior variants), falling to 1.5-3 when the cold branch carries weight. Bridge: P(Tk<=30) <= 0.0007, X_C 52 [45,64]. S: P(Tk<=30) = 0.01-0.11, X_S>~65. Per-datum terms: out/q42/branch_ratio_terms.txt (the hot branch overpredicts H13CN/HCN 1-0 by ~2x at X=45: tau(HCN 1-0)~2, which pulls X_N up to 58).'),
 unit='probability; Bayes factor',uncertainty='X prior (LN(45,0.2 dex) vs flat 22-100 vs flat to 178), band-scale priors (10/15, 20/25%), choice of 13C extraction',
 confidence='low',evidence=EV0,assumptions=ASM))
json.dump(R,open('/output/report.json','w'),indent=1)
print(len(R['results']))
